            ((event_edge == EDGE_RISING) && ((edge_interest[SIGNAL_CRCINREADY] & 1) != 0)) ||
            ((event_edge == EDGE_FALLING) && ((edge_interest[SIGNAL_CRCINREADY] & 2) != 0))) begin
          run_step(PHASE_EDGE, SIGNAL_CRCINREADY, event_edge, requests);
          service_requests(requests);
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
          calendar_drain_phases();
`endif
        end
      end
    end
  endtask

  task automatic observe_signal_5();
    int requests;
    int event_edge;
    while (status == 0) begin
      @(mat_load_ready);
`ifdef CPPTB_SV_DPI_TIMING
      note_time_step();
`endif
      if (status == 0) begin
        event_edge = mat_load_ready ? EDGE_RISING : EDGE_FALLING;
        if (
            ((event_edge == EDGE_RISING) && ((edge_interest[SIGNAL_MATLOADREADY] & 1) != 0)) ||
            ((event_edge == EDGE_FALLING) && ((edge_interest[SIGNAL_MATLOADREADY] & 2) != 0))) begin
          run_step(PHASE_EDGE, SIGNAL_MATLOADREADY, event_edge, requests);
          service_requests(requests);
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
          calendar_drain_phases();
`endif
        end
      end
    end
  endtask

  initial begin
    clk = 1'b0;
    rst_n = '0;
    fir_in_valid = '0;
    fir_in_sample = '0;
    fir_out_ready = '0;
    crc_in_valid = '0;
    crc_in_data = '0;
    crc_in_last = '0;
    crc_out_ready = '0;
    mat_load_valid = '0;
    mat_load_select = '0;
    mat_load_index = '0;
    mat_load_data = '0;
    mat_start = '0;
    mat_out_ready = '0;
    sim_cycles = 0;
    timer_generation = 0;
    timer_deadline = NO_TIMER;
    timer_owner_target = NO_TIMER;
    iterations = 1000;
    status = 0;
    track_falling_edges = 1'b0;
    clock_drivers_active = 1'b0;
`ifdef CPPTB_SV_DPI_TIMING
    phase_requests = 0;
    phase_barrier_token = 1'b0;
    last_started_time = $time;
`endif
    void'($value$plusargs("HEAVY_BENCH_ITERS=%d", iterations));

    for (int i = 0; i < INPUT_WORD_COUNT; i++) begin
      in_words[i] = '0;
    end
    for (int i = 0; i < OUTPUT_WORD_COUNT; i++) begin
      out_words[i] = '0;
    end
    for (int i = 0; i < CPPTB_SIGNAL_COUNT; i++) begin
      edge_interest[i] = '0;
      registered_clock[i] = 1'b0;
      primary_clock[i] = 1'b0;
    end

    heavy_dpi_init(iterations, TIMEPRECISION_FS);
`ifdef CPPTB_ENABLE_SV_LOGGING
    cpptb_log_pkg::configure();
`endif
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
    calendar_initialize();
`endif
    run_step(PHASE_INIT, NO_SIGNAL, EDGE_RISING, initial_requests);
    service_requests(initial_requests);
    clock_drivers_active = 1'b1;
    if (status == 0) begin
      fork
`ifdef CPPTB_SV_DPI_CALENDAR_TIMING
        calendar_owner();
`else
        timer_owner();
`ifdef CPPTB_SV_DPI_TIMING
        phase_pump();
`endif
        drive_clock_0();
`endif
        observe_signal_0();
        observe_signal_1();
        observe_signal_2();
        observe_signal_3();
        observe_signal_4();
        observe_signal_5();
      join_none
    end

    wait (status != 0);
    timer_generation++;
    if (status < 0) begin
      $fatal(1, "heavy_benchmark_dut DPI testbench failed");
    end
    $finish;
  end

  heavy_benchmark_dut i_dut (
      .clk(clk),
      .rst_n(rst_n),
      .fir_in_valid(fir_in_valid),
      .fir_in_ready(fir_in_ready),
      .fir_in_sample(fir_in_sample),
      .fir_out_valid(fir_out_valid),
      .fir_out_ready(fir_out_ready),
      .fir_out_result(fir_out_result),
      .fir_sample_count(fir_sample_count),
      .crc_in_valid(crc_in_valid),
      .crc_in_ready(crc_in_ready),
      .crc_in_data(crc_in_data),
      .crc_in_last(crc_in_last),
      .crc_out_valid(crc_out_valid),
      .crc_out_ready(crc_out_ready),
      .crc_out_result(crc_out_result),
      .crc_packet_count(crc_packet_count),
      .mat_load_valid(mat_load_valid),
      .mat_load_ready(mat_load_ready),
      .mat_load_select(mat_load_select),
      .mat_load_index(mat_load_index),
      .mat_load_data(mat_load_data),
      .mat_start(mat_start),
      .mat_out_valid(mat_out_valid),
      .mat_out_ready(mat_out_ready),
      .mat_out_index(mat_out_index),
      .mat_out_data(mat_out_data),
      .mat_block_count(mat_block_count)
  );

endmodule : dpi_heavy_benchmark
